const input = $input.first().json;

const body =
  input.body && typeof input.body === 'object'
    ? input.body
    : input;

const question =
  typeof body.question === 'string'
    ? body.question.trim()
    : '';

if (!question) {
  throw new Error(
    'UI Planner input error: question must be a non-empty string.'
  );
}

return [
  {
    json: {
      question,
      openaiModel:
        typeof body.openaiModel === 'string' && body.openaiModel.trim()
          ? body.openaiModel.trim()
          : 'gpt-5-mini',
    },
  },
];

const plan = $input.first().json;

const question =
  typeof plan.question === 'string'
    ? plan.question.trim()
    : '';

if (!question) {
  throw new Error(
    'UI Planner response error: question must be a non-empty string.'
  );
}

if (
  !Array.isArray(plan.agents) ||
  plan.agents.length < 1 ||
  plan.agents.length > 10
) {
  throw new Error(
    'UI Planner response error: agents must contain 1 to 10 entries.'
  );
}

const agents = plan.agents.map((agent, index) => {
  if (!agent || typeof agent !== 'object') {
    throw new Error(
      `UI Planner response error: agent at index ${index} must be an object.`
    );
  }

  const agentId =
    Number.isInteger(agent.agent_id)
      ? agent.agent_id
      : Number.isInteger(agent.agentId)
        ? agent.agentId
        : index + 1;

  const role =
    typeof agent.role === 'string'
      ? agent.role.trim()
      : '';

  const task =
    typeof agent.task === 'string'
      ? agent.task.trim()
      : '';

  if (
    agentId < 1 ||
    agentId > 10 ||
    !role ||
    !task
  ) {
    throw new Error(
      `UI Planner response error: invalid agent at index ${index}. ` +
      `agentId=${agentId}, role=${JSON.stringify(role)}, ` +
      `task length=${task.length}.`
    );
  }

  return {
    agentId,
    role,
    task,
  };
});

const model =
  typeof plan.model === 'string' && plan.model.trim()
    ? plan.model.trim()
    : typeof plan.openaiModel === 'string' && plan.openaiModel.trim()
      ? plan.openaiModel.trim()
      : 'gpt-5-mini';

const questionType =
  typeof plan.questionType === 'string' && plan.questionType.trim()
    ? plan.questionType.trim()
    : typeof plan.question_type === 'string' && plan.question_type.trim()
      ? plan.question_type.trim()
      : 'genel';

const complexity =
  typeof plan.complexity === 'string' && plan.complexity.trim()
    ? plan.complexity.trim()
    : 'low';

return [
  {
    json: {
      question,
      model,
      openaiModel: model,
      questionType,
      complexity,
      agentCount: agents.length,
      agents,
    },
  },
];
